class Solution:
    def ipToCIDR(self, ip: str, n: int) -> List[str]:
        def fmt(x, p):
            return '.'.join(str((x >> s) & 255) for s in (24, 16, 8, 0)) + '/' + str(p)
        x = 0
        for part in map(int, ip.split('.')):
            x = (x << 8) | part
        res = []
        while n > 0:
            low = x & (-x)
            if low == 0 or low > n:
                low = n & (-n)
            size = min(low, n)
            prefix = 32 - size.bit_length() + 1
            res.append(fmt(x, prefix))
            x += size
            n -= size
        return res

