var ipToCIDR = function(ip, n) {
    let p = ip.split('.').map(Number);
    let x = ((p[0] * 256 + p[1]) * 256 + p[2]) * 256 + p[3];
    let res = [];
    const ctz = v => { let c = 0; while ((v & 1) === 0) { v >>>= 1; c++; } return c; };
    while (n > 0) {
        let low = x === 0 ? 4294967296 : (x & -x);
        let size = Math.min(low, n);
        let prefix = 32 - ctz(size);
        let s = [(x >>> 24) & 255, (x >>> 16) & 255, (x >>> 8) & 255, x & 255].join('.');
        res.push(s + '/' + prefix);
        x += size;
        n -= size;
    }
    return res;
};
